<script setup lang="ts">
import { computed, onBeforeUnmount, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import UiButton from '@/components/ui/UiButton.vue'
import UiBadge from '@/components/ui/UiBadge.vue'
import UiDialog from '@/components/ui/UiDialog.vue'
import UiNotice from '@/components/ui/UiNotice.vue'
import UiPageState from '@/components/ui/UiPageState.vue'
import OwnerField from '@/components/owner/OwnerField.vue'
import OwnerPager from '@/components/owner/OwnerPager.vue'
import OccupancyPicker from '@/components/billing/OccupancyPicker.vue'
import { eventPayload, localEventTime, useOwnerApi } from '@/composables/useOwnerApi'
import { toApiError } from '@/lib/api'
import { decimalText, inputTime } from '@/lib/billing'
import { formatDateTime } from '@/lib/notifications'
import { formatUnitPrice } from '@/lib/unit-price'
import type { Occupancy, PageResult } from '@/types/owner'
import type { Invoice, MeterReading } from '@/types/billing'
function routeOccupancy(value: unknown) { if (typeof value !== 'string' || !/^[1-9]\d*$/.test(value)) return null; const id = Number(value); return Number.isSafeInteger(id) ? id : null }
const route = useRoute(), router = useRouter(), client = useOwnerApi(), occupancyId = ref<number | null>(routeOccupancy(route.query.occupancy_id))
const occupancy = ref<Occupancy | null>(null), readings = ref<MeterReading[]>([]), lockedMonths = ref<string[]>([]), loading = ref(false), loadError = ref(''), success = ref(''), month = ref(''), page = ref(1)
const modal = ref(false), editing = ref<MeterReading | null>(null), deleting = ref<MeterReading | null>(null), reviewing = ref(false)
const form = ref({ occupancy_service_id: '', period_start: '', period_end: '', previous_reading: '', current_reading: '' })
let sequence = 0, alive = true
const services = computed(() => occupancy.value?.services?.filter(item => item.billing_method === 'metered') ?? [])
const selectedService = computed(() => services.value.find(item => item.id === Number(form.value.occupancy_service_id)))
const filtered = computed(() => readings.value.filter(item => !month.value || item.billing_month === month.value))
const visible = computed(() => filtered.value.slice((page.value - 1) * 15, page.value * 15))
const lastPage = computed(() => Math.max(1, Math.ceil(filtered.value.length / 15)))
async function all<T>(path: string, params = {}): Promise<T[]> { const values: T[] = []; let p = 1, last = 1; do { const result = await client.get<PageResult<T>>(path, { ...params, per_page: 100, page: p }); values.push(...result.data); last = result.meta.last_page; p++ } while (p <= last); return values }
async function load() { const id = occupancyId.value, current = ++sequence; occupancy.value = null; readings.value = []; lockedMonths.value = []; loadError.value = ''; page.value = 1; if (!id) return; loading.value = true; try { const [detail, history, invoices] = await Promise.all([client.get<{ data: Occupancy }>(`/occupancies/${id}`), all<MeterReading>(`/occupancies/${id}/meter-readings`), all<Invoice>('/invoices', { occupancy_id: id })]); if (alive && current === sequence) { occupancy.value = detail.data; readings.value = history; lockedMonths.value = invoices.map(item => item.billing_month) } } catch (caught) { if (alive && current === sequence) loadError.value = toApiError(caught).message } finally { if (alive && current === sequence) loading.value = false } }
function lockedReason(item: MeterReading) { if (item.is_billed || lockedMonths.value.includes(item.billing_month)) return 'Tháng đã phát hành hóa đơn'; const later = readings.value.some(other => other.occupancy_service.service_id === item.occupancy_service.service_id && (other.period_end > item.period_end || (other.period_end === item.period_end && other.id > item.id))); return later ? 'Đã có kỳ chỉ số tiếp theo' : '' }
function startEdit(item?: MeterReading) { editing.value = item ?? null; client.clearError(); reviewing.value = false; form.value = item ? { occupancy_service_id: String(item.occupancy_service_id), period_start: inputTime(item.period_start), period_end: inputTime(item.period_end), previous_reading: item.previous_reading, current_reading: item.current_reading } : { occupancy_service_id: services.value.length === 1 ? String(services.value[0]!.id) : '', period_start: '', period_end: localEventTime(), previous_reading: '', current_reading: '' }; modal.value = true; if (!item) suggestBaseline() }
function suggestBaseline() { if (editing.value) return; const service = selectedService.value; if (!service) return; const previous = readings.value.find(item => item.occupancy_service.service_id === service.service_id); form.value.period_start = inputTime(previous?.period_end ?? service.effective_from); form.value.previous_reading = previous?.current_reading ?? ''; if (service.effective_until) form.value.period_end = inputTime(service.effective_until) }
async function save() { const id = occupancyId.value; if (!id || !reviewing.value) return; try { await client.write(editing.value ? 'put' : 'post', `/occupancies/${id}/meter-readings${editing.value ? `/${editing.value.id}` : ''}`, { ...form.value, occupancy_service_id: Number(form.value.occupancy_service_id), period_start: eventPayload(form.value.period_start), period_end: eventPayload(form.value.period_end) }); modal.value = false; success.value = editing.value ? 'Đã cập nhật kỳ chỉ số.' : 'Đã ghi chỉ số điện nước.'; await load() } catch { reviewing.value = false } }
async function remove() { if (!deleting.value || !occupancyId.value) return; try { await client.write('delete', `/occupancies/${occupancyId.value}/meter-readings/${deleting.value.id}`); deleting.value = null; success.value = 'Đã xóa kỳ chỉ số cuối.'; await load() } catch { /* Dialog retains errors for manual correction. */ } }
watch(occupancyId, id => { modal.value = false; deleting.value = null; success.value = ''; if (routeOccupancy(route.query.occupancy_id) !== id) void router.replace({ query: { ...route.query, occupancy_id: id ? String(id) : undefined } }); void load() }, { immediate: true })
watch(() => route.query.occupancy_id, value => { const id = routeOccupancy(value); if (id !== occupancyId.value) occupancyId.value = id })
watch(month, () => { page.value = 1 })
onBeforeUnmount(() => { alive = false; sequence++ })
</script>
<template><section class="management-page"><header class="management-header"><div><span class="eyebrow">Điện nước & tính tiền</span><h1>Chỉ số điện nước</h1><p>Ghi chỉ số thực tế cho từng phòng và khoảng giá đã áp dụng.</p></div><div class="button-row"><RouterLink class="record-link" to="/owner/meters/bulk">Nhập nhiều phòng →</RouterLink><RouterLink class="record-link" to="/owner/invoices/new">Lập hóa đơn →</RouterLink></div></header><div class="record-card"><OccupancyPicker v-model="occupancyId" /></div><UiNotice v-if="success" tone="success">{{ success }}</UiNotice><UiPageState v-if="loading" kind="loading" /><UiPageState v-else-if="loadError" kind="error" :description="loadError"><UiButton @click="load">Thử lại</UiButton></UiPageState><template v-else-if="occupancy"><div class="management-toolbar" style="margin-top:24px"><div><strong>Phòng {{ occupancy.room.room_number }} · {{ occupancy.group.group_code }}</strong><p class="help-text">{{ formatDateTime(occupancy.started_at) }} → {{ occupancy.ended_at ? formatDateTime(occupancy.ended_at) : 'Đang thuê' }}</p></div><label>Tháng chỉ số<input v-model="month" type="month" class="ui-input" /></label><UiButton variant="ghost" @click="month = ''">Tất cả tháng</UiButton><UiButton :disabled="!services.length" @click="startEdit()">Ghi chỉ số mới</UiButton><UiButton variant="secondary" @click="load">Làm mới</UiButton></div><UiNotice v-if="!services.length" tone="warning">Đợt thuê chưa áp dụng dịch vụ điện/nước tính theo chỉ số. <RouterLink :to="`/owner/stays/${occupancy.id}`">Mở đợt thuê để áp dụng dịch vụ</RouterLink>.</UiNotice><p class="help-text">Chỉ sửa/xóa kỳ cuối chưa khóa. Kỳ cần tiếp nối chỉ số trước, nằm trong cùng tháng và đúng khoảng áp dụng giá. Tháng đã phát hành hóa đơn sẽ được khóa.</p><UiPageState v-if="!visible.length" title="Chưa có chỉ số phù hợp" description="Chọn đúng tháng hoặc ghi kỳ chỉ số đầu tiên." /><div v-else class="management-grid"><article v-for="reading in visible" :key="reading.id" class="record-card"><header><div><h2>{{ reading.occupancy_service.service.name }}</h2><span class="help-text">Tháng {{ reading.billing_month }}</span></div><UiBadge :tone="lockedReason(reading) ? 'neutral' : 'success'">{{ lockedReason(reading) ? 'Đã khóa' : 'Kỳ cuối có thể sửa' }}</UiBadge></header><dl class="record-facts"><div><dt>Khoảng ghi</dt><dd>{{ formatDateTime(reading.period_start) }}<br />→ {{ formatDateTime(reading.period_end) }}</dd></div><div><dt>Chỉ số đầu → cuối</dt><dd>{{ decimalText(reading.previous_reading) }} → {{ decimalText(reading.current_reading) }}</dd></div><div><dt>Tiêu thụ</dt><dd><strong>{{ decimalText(reading.consumption) }} {{ reading.occupancy_service.unit }}</strong></dd></div><div><dt>Đơn giá chốt</dt><dd>{{ formatUnitPrice(reading.occupancy_service.unit_price) }}</dd></div></dl><p v-if="lockedReason(reading)" class="help-text">{{ lockedReason(reading) }}</p><footer><template v-if="!lockedReason(reading)"><UiButton variant="secondary" :aria-label="`Sửa chỉ số ${reading.occupancy_service.service.name} tháng ${reading.billing_month}`" @click="startEdit(reading)">Sửa kỳ chỉ số</UiButton><UiButton variant="ghost" :aria-label="`Xóa chỉ số ${reading.occupancy_service.service.name} tháng ${reading.billing_month}`" @click="deleting = reading; client.clearError()">Xóa</UiButton></template><RouterLink v-if="reading.invoice_id" class="record-link" :to="`/owner/invoices/${reading.invoice_id}`">Xem hóa đơn</RouterLink></footer></article></div><OwnerPager v-if="filtered.length" :page="page" :last-page="lastPage" :total="filtered.length" @change="page = $event" /></template><UiPageState v-else title="Chọn đợt thuê để bắt đầu" description="Bạn có thể ghi chỉ số cho đợt đang thuê hoặc bổ sung kỳ cuối cho đợt đã trả phòng." />
<UiDialog :open="modal" :title="editing ? 'Sửa kỳ chỉ số' : 'Ghi chỉ số mới'" description="Thời gian theo giờ Việt Nam. Nhập chỉ số thực tế, không nhập lượng tiêu thụ." @update:open="value => { if (!client.busy.value) modal = value }"><p v-if="client.error.value" class="form-error" role="alert">{{ client.error.value }}</p><form v-if="!reviewing" class="form-grid" @submit.prevent="reviewing = true"><fieldset class="form-grid" :disabled="client.busy.value"><label class="select-field">Dịch vụ / khoảng giá<select v-model="form.occupancy_service_id" required class="ui-select" :disabled="!!editing" @change="suggestBaseline"><option value="">Chọn dịch vụ</option><option v-for="service in services" :key="service.id" :value="String(service.id)">{{ service.service.name }} · {{ formatUnitPrice(service.unit_price) }} / {{ service.unit }} · từ {{ formatDateTime(service.effective_from) }}</option></select></label><p v-if="client.errors.value.occupancy_service_id" class="field-error">{{ client.errors.value.occupancy_service_id[0] }}</p><OwnerField v-model="form.period_start" label="Đầu kỳ (giờ Việt Nam)" name="period_start" type="datetime-local" step="1" required :errors="client.errors.value" /><OwnerField v-model="form.period_end" label="Cuối kỳ (giờ Việt Nam)" name="period_end" type="datetime-local" step="1" required :errors="client.errors.value" /><OwnerField v-model="form.previous_reading" label="Chỉ số đầu kỳ" name="previous_reading" type="number" min="0" step="0.001" required :errors="client.errors.value" /><OwnerField v-model="form.current_reading" label="Chỉ số cuối kỳ" name="current_reading" type="number" min="0" step="0.001" required :errors="client.errors.value" /></fieldset><UiButton type="submit">Xem lại chỉ số</UiButton></form><template v-else><div class="review-box"><h3>Xem lại kỳ chỉ số</h3><p>{{ selectedService?.service.name }} · {{ form.previous_reading }} → {{ form.current_reading }} {{ selectedService?.unit }}</p><p>{{ formatDateTime(eventPayload(form.period_start)) }} → {{ formatDateTime(eventPayload(form.period_end)) }}</p></div><div class="button-row"><UiButton variant="secondary" :disabled="client.busy.value" @click="reviewing = false">Quay lại sửa</UiButton><UiButton :loading="client.busy.value" @click="save">Xác nhận lưu chỉ số</UiButton></div></template></UiDialog>
<UiDialog :open="!!deleting" title="Xóa kỳ chỉ số cuối?" description="Kỳ chưa lập hóa đơn sẽ bị xóa. Kiểm tra lại dịch vụ và thời gian trước khi xác nhận." @update:open="value => { if (!value && !client.busy.value) deleting = null }"><p>{{ deleting?.occupancy_service.service.name }} · {{ formatDateTime(deleting?.period_start ?? null) }} → {{ formatDateTime(deleting?.period_end ?? null) }}</p><p v-if="client.error.value" class="form-error" role="alert">{{ client.error.value }}</p><template #actions><UiButton variant="secondary" :disabled="client.busy.value" @click="deleting = null">Giữ lại</UiButton><UiButton :loading="client.busy.value" @click="remove">Xác nhận xóa</UiButton></template></UiDialog></section></template>
